{
  "name": "@ship-cli/opencode",
  "version": "0.2.3",
  "type": "module",
  "description": "OpenCode plugin for Ship - Linear task management integration",
  "license": "MIT",
  "main": "src/plugin.ts",
  "files": [
    "src",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "plugin",
    "ship",
    "linear",
    "task-management",
    "ai"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/EduSantosBrito/ship-cli.git",
    "directory": "packages/opencode-plugin"
  },
  "homepage": "https://github.com/EduSantosBrito/ship-cli#readme",
  "bugs": {
    "url": "https://github.com/EduSantosBrito/ship-cli/issues"
  },
  "author": "Eduardo Santos de Brito",
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "check": "tsc --noEmit",
    "lint": "oxlint",
    "format": "oxfmt --write src/",
    "format:check": "oxfmt src/",
    "test": "vitest run",
    "test:watch": "vitest",
    "prepare": "effect-language-service patch --module typescript"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.2",
    "@opencode-ai/sdk": "^1.1.2",
    "effect": "^3.19.14"
  },
  "devDependencies": {
    "@effect/language-service": "^0.64.1",
    "@effect/vitest": "^0.27.0",
    "@types/bun": "latest",
    "@types/node": "^25.0.3",
    "oxfmt": "^0.21.0",
    "oxlint": "^1.36.0",
    "typescript": "~5.9.3",
    "vitest": "^4.0.16"
  },
  "engines": {
    "bun": ">=1.0.0"
  }
}
